def countDistinctPoints(n, segments):
    # Initialize a set to store unique x-coordinates of points
    x_set = set()
    # Iterate through each segment
    for Ax, Ay, Bx, By in segments:
        # If x-coordinates of a segment are different, add the x-coordinate to the set
        if Ax != Bx:
            x_set.add(Ax)
            x_set.add(Bx)
        # If there's an intersection with other segments, add the line's x-coordinate to the set
        if Ax == Ay and Bx == By:
            if Ax != Bx:
                x_set.add((Ax + Bx) / 2)
            x_set.add((Ay + By) / 2)
        # If y-coordinates are different, add the y-coordinate to the set
        if Ay != By:
            y_set = {(Ax + By) / 2, (By + Ay) / 2}
            for x in x_set:
                x_set.add(x in y_set)
            for x in y_set:
                x_set.add(x in y_set)
            y_set.remove(x)
            x_set = y_set

    # Return the size of the set sifo distinct points
    return len(x_set)

