import sys

def can_reset_to_zero(roads, v, s, t):
    """Determine if the car can reset to 0 on its odometer by driving along roads."""
    current_distance = 0
    for start, end, length in roads:
        if start != v:
            continue
        else:
            if v == end:
                if not (s == 0 and t == current_distance + length):
                    # Car must reset at start when not at end
                    return False
            current_distance += length
            if current_distance > t:
                return False
    return (s == 0 and t == current_distance)

