def dijkstra(edges, start):
    vertexes = defaultdict(dict)
    for a, b in edges:
        vertexes[a][b] = vertexes[b][a] = True

    dis = {}
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)

        if u not in dis:
            dis[u] = d
            for v in vertexes[u]:
                h = d + vertexes[u][v]
                if h < dis.get(v, float('inf')):
                    dis[v] = h
                    heapq.heappush(pq, (h, v))
    return dis

