def is_cool_cycle(r, c, grid, visited):
    queue = [(r, c)]
    while queue:
        r, c = queue.pop(0)
        if grid[r][c] == '1' and visited[r][c] == 0:
            visited[r][c] = 1
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and visited[nr][nc] == 0:
                    queue.append((nr, nc))
    return all(visited[r][c] == 1 for r in range(n) for c in range(m))

def longest_cool_cycle(n, m, grid):
    max_length = 0
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '1' and not visited[r][c]:
                visited[r][c] = 1
                if is_cool_cycle(r, c, grid, visited):
                    candidate_length = (r - prev_r + 1) * (c - prev_c + 1) + len(visited)
                    max_length = max(max_length, candidate_length)
                prev_r, prev_c = r, c
                visited[r][c] = 0
    return max_length

