import heapq
from collections import defaultdict, deque


def dijkstra(graph, start, end, initial_queries):
    INF = float('inf')
    dist = {v: INF for v in graph}
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, v = heapq.heappop(pq)
        if d != dist[v]:
            continue
        for nv, nd in graph[v]:
            if dist[nv] > dist[v] + nd:
                dist[nv] = dist[v] + nd
                heapq.heappush(pq, (dist[nv], nv))

    result = []
    for v, u in initial_queries:
        parent = {}
        parent[v] = v
        stack = [v]
        while stack:
            v = stack.pop()
            for nv, nd in graph[v]:
                nd -= dist[u] - dist[nv]
                if nd < 0 or nd >= dist[nv] or nd >= dist[u]:
                    continue
                nd -= dist[v] - dist[u] if dist[v] != dist[u] else 0
                if nv in parent and nd < dist[nv]:
                    continue
                parent[nv] = v
                stack.append(nv)

        result.append(min(parent.keys()))

    return result


