            if visited[i]:
                continue
            for j in graph[i]:
                if visited[j]:
                    continue
                visited[j], last_pos, observed, elapsed = 1, j, [i], 1
                while elapsed > 0 and not find_path_or_no(n, observed):
                    elapsed -= 1
                    for child in graph[visited[0]]:
                        if visited[child]:
                            visited[0], last_pos, observed, elapsed = 1, j, [visited.pop(0)], 1
                            continue
                        if child not in visited and visited[0] not in graph[child]:
                            visited.append(child)
                    if not elapsed:
                        last_pos = 0
                        visited[0], last_pos, observed, elapsed = 0, j, [], -1
