    def build_graph(n, roads):
        graph = [[] for _ in range(n + 1)]
        for a, b, cost in roads:
            graph[a].append((b, cost))
            graph[b].append((a, -cost))  # Negate for undirected graph
        return graph

    def dijkstra(graph, start):
        distances = [float('inf')] * (n + 1)
        distances[start] = 0
        priority_queue = [(0, start)]
        while priority_queue:
            current_distance, current_node = priority_queue.pop(0)
            if current_distance > distances[current_node]:
                continue
            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    priority_queue.append((distance, neighbor))
        return distances

    graph = build_graph(n, roads)
    for v, s, t in cars:
        graph = build_graph(n, roads)
        postfix = dijkstra(graph, v + 1)
        reset_time = t
        while reset_time > 0 and reset_time - (postfix[v] - s) % reset_time >= 0 and reset_time - (postfix[v] - s) % reset_time != reset_time:
            reset_time -= (postfix[v] - s) % reset_time
            if reset_time == 0:
