import heapq
from collections import defaultdict
from itertools import pairwise
from itertools import permutations
from collections import defaultdict
from math import inf

def dijkstra(adj, start):
    distance = defaultdict(lambda: inf)
    distance[start] = 0
    pq = []
    heapq.heappush(pq, (0, start))

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_distance > distance[current_node]:
            continue

        for neighbor, edge_distance in adj[current_node]:
            distance_neighbor = current_distance + edge_distance

            if distance[current_node] + edge_distance < distance[neighbor]:
                distance[neighbor] = distance_neighbor
                heapq.heappush(pq, (distance_neighbor, neighbor))

    return distance

def lexicographical_min_path(adj, v, u):
    distance_vu = dijkstra(adj, v)

    order = sorted([vertex for vertex in distance_vu], key=lambda x: distance_vu[x])

    distance_min_vu = {}
    for current_vu in [v] + order:
        current_dist_vu = dijkstra(adj, v).get(current_vu)

        if not current_dist_vu:
            current_dist_vu = inf

        distance_min_vu[current_vu] = current_dist_vu
    for v2, v3 in pairwise(order):
