def find_longest_cool_cycle(n, m, grid):
    def is_cool_cycle(path, cycle):
        grid_set = {(i, j) for i in range(n) for j in range(m)}
        cycle_set = {(i, j) for i in range(n // len(path)) for j in range(m // len(cycle)) for i_p, j_p in zip(path, cycle)}
        if grid_set & cycle_set:
            for i, cond in enumerate((set(path[i + 1]) & set(cycle[i * len(path) + 1 : (i + 1) * len(path) + 1]) == {1} for path, cycle in cycle * 2)):
                if cond:
                    return True
        return len(grid_set & set(cycle)) == len(cycle)

    cycle_sets = []
    for m_strides in combinations(range(n), m):
        path = deque()
        for m_strides_r, m_strides_c in zip(m_strides, list(product(*[[0, 1]] * m))):
            path.append((0, m_strides_r, m_strides_c + 1))
        grid_path = tuple(map(''.join, zip(*[iter(grid)] * 4)))
        for c_strides in combinations(range(m), n):
            cycle = deque((path[i % len(path)][0] + m_strides_r for i, m_strides_r in enumerate(m_strides)))
            cycle.extend(c_strides)
            for m_strides_c, m_strides_r, r in zip(m_strides, c_strides, range(n)):
                path.appendleft((path[0][0] + m_strides_r, path[-1][1], path[-1][-1]))
            cycle.extend(leftopposite(p) for p in path)
            grid_cycle = tuple(''.join((''.join(digit) for x, y in eight for digit in (x * n + y // 10, y % 10)))[1:] for r in range(n))
            cycle_set = set(((0, y // 10, y % 10) for y in set(grid_cycle) - set(grid_path)))
            cycle = grid_cycle[:len(cycle)][::cycle_set].copy()
            if is_cool_cycle(path, cycle):
                cycle_sets.append(len(cycle))
    return max(cycle_sets or [0])

