import heapq
import sys

def dijkstra(graph, start):
    n = len(graph)
    distances = [float('inf')] * n
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_vertex = heapq.heappop(priority_queue)

        if current_distance > distances[current_vertex]:
            continue

        for neighbor, weight in graph[current_vertex].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def count_connected_components(graph, edges, m):
    query_results = []

    for _ in range(m):
        start_vertex, end_vertex = map(int, input().split())

        shortest_path = dijkstra(graph, start_vertex)

        for edge_vertex, weight in edges:
            if shortest_path[edge_vertex] > weight:
                shortest_path[edge_vertex] = weight

        # Add all vertices in shortest path to avoid counting them again
        for vertex in shortest_path:
            if shortest_path[vertex] == float('inf'):
                shortest_path[vertex] = 0

        # Find disconnected vertices
        disconnected_vertices = [v for v in range(n) if shortest_path[v] == float('inf')]

        # Increment query result for each disconnected vertex
        query_results.append(len(disconnected_vertices))

    return query_results

