def find_energy(s, e, ghost_time, ghost_level, energy):
    level = ghost_level + math.ceil((e - int(e) + 1 - 5 * 1e-18) / (ghost_time - int(e) + 1 - 5 * 1e-18))
    if energy - s[level] < 0:
        return -1
    if energy > s[level] + level:
        return -1
    return math.floor(energy / (level + 1) + level + 1)

def minimum_energy(total_energy, initial_time, person_location, *ghost_times_and_ranges):
    min_energy = total_energy
    for time in range(1, 21):
        for speed in range(2, person_location // 2):
            energy = ((speed + person_location - 1) / speed + 1) * (speed + 1) * (person_location + 1) * person_location * math.floor(math.sqrt((total_energy - speed * (speed + 1) * (speed + 2)) / total_energy))
            manhattan_sum = speed * time * person_location + min_energy(low_energy, high_energy(ghost_time, ghost_level, total_energy)) * time
            min_energy = min(manhattan_sum, min_energy)
    return min_energy

def low_energy(ghost_time, ghost_level, energy):
