def query_colorfulness(l: int, r: int, colors: list, color_frequencies: dict):
    prefix_sum = [0]
    color_sum = 0
    for unit in colors:
        color_sum += unit
        prefix_sum.append(prefix_sum[-1] + color_sum)

    result = 0
    for unit in range(l - 1, r):
        accumulated_color_diff = prefix_sum[unit + 1] - prefix_sum[l - 1]
        coloring_diff = colors[unit] - unit
        result += accumulated_color_diff + coloring_diff * (unit - l + 1)
    return result

def main():
