                    current_color_sum += color
                current_color_frequencies[color] = current_color_frequencies.get(color, 0) + 1
            for unit in range(l - 1, r):
                accumulated_color_diff = prefix[unit + 1] - prefix[l - 1]
                color_rep_count = current_color_frequencies[colors[unit] - 1]
                painting_cost = accumulated_color_diff + color_rep_count * (unit - l + 1)
                priority_index = 0
                for neighbor_color in range(unit + 1, r + 1):
                    if sorted([-current_color_frequencies[colors[neighbor_color] - 1], painted_cost]) == sorted([-current_color_frequencies[colors[unit] - 1], painting_cost]):
                        painting_cost = max(painting_cost, accumulated_color_diff + current_color_frequencies[colors[neighbor_color] - 1] * (unit - l + 1))
                        priority_index = neighbor_color
                current_color_frequencies[priority_index] += current_color_frequencies.pop(colors[unit] - 1)
            colors[:] = [x if colors[u] != x else prefix[unit] for u in range(l - 1, r)]
            prefix = current_color_sum
        if type_ == 2:
            l, r = values
            print(query_colorfulness(l, r, colors, color_frequencies))

if __name__ == "__main__":
    main()

